const SEVERITY_WEIGHT = {
	high: 3,
	medium: 2,
	low: 1
};
/**
* Scan exact prose with deterministic, source-offset-preserving rules.
* @param text - exact Asset model text or materialized ChangeSet candidate.
* @param options - provider-owned sample and result bounds.
* @returns a stable JSON-safe report; insufficient samples remain explicit.
*/
function scanNoAi(text, options) {
	validateOptions(options);
	let characterCount = 0;
	for (const character of text) if (!/\s/u.test(character)) characterCount += 1;
	const sampleLevel = characterCount < options.minCharacters ? "insufficient" : characterCount < options.strongSampleCharacters ? "usable" : "strong";
	const findings = [];
	const seen = /* @__PURE__ */ new Set();
	for (const rule of RULES) for (const pattern of rule.patterns) {
		pattern.lastIndex = 0;
		for (const match of text.matchAll(pattern)) {
			const start = match.index;
			const evidence = match[0];
			if (evidence.length === 0) continue;
			const key = `${rule.id}:${start}:${evidence.length}`;
			if (seen.has(key)) continue;
			seen.add(key);
			findings.push({
				ruleId: rule.id,
				label: rule.label,
				severity: rule.severity,
				startUtf16: start,
				endUtf16: start + evidence.length,
				evidence,
				advice: rule.advice
			});
		}
	}
	findings.sort((left, right) => SEVERITY_WEIGHT[right.severity] - SEVERITY_WEIGHT[left.severity] || left.startUtf16 - right.startUtf16 || left.ruleId.localeCompare(right.ruleId));
	const counts = findings.reduce((result, finding) => {
		result[finding.severity] += 1;
		return result;
	}, {
		high: 0,
		medium: 0,
		low: 0
	});
	const weighted = findings.reduce((total, finding) => total + SEVERITY_WEIGHT[finding.severity], 0);
	const densityBase = Math.max(1, characterCount / 1e3);
	const riskScore = sampleLevel === "insufficient" ? 0 : Math.min(100, Math.round(weighted * 8 / densityBase));
	return {
		version: 1,
		characterCount,
		sampleLevel,
		riskScore,
		counts,
		findings: findings.slice(0, options.maxFindings)
	};
}
function validateOptions(options) {
	for (const [name, value] of Object.entries(options)) if (!Number.isSafeInteger(value) || value < 1) throw new TypeError(`novel-analysis: ${name} must be a positive integer`);
	if (options.strongSampleCharacters < options.minCharacters) throw new TypeError("novel-analysis: strongSampleCharacters must not be smaller than minCharacters");
}
